def ensure_dependencies():
    tools = ['gdparse', 'gdformat', 'gdlint', 'gdmetrics', 'gdstyle']
    missing = [t for t in tools if not shutil.which(t)]
    if missing: subprocess.run(['pip', 'install', '--user', 'gdtoolkit'], check=True)

def safe_query(sql, params=()):
    try: cursor.execute(sql, params)
    except sqlite3.OperationalError:
        ensure_database()
        cursor.execute(sql, params)
        if cursor.rowcount == 0: raise RuntimeError('Query failed after recovery')

